mapper.select:
SELECT p.id AS id, p.plate_no AS plateNo, p.space_id AS spaceId, p.end_time AS endTime, p.status AS status, p.area_id AS areaId, a.name AS areaName, p.operator_id AS operatorId, u.nickname AS operatorName, p.order_no AS orderNo, p.remark AS remark, p.reserve1 AS reserve1, p.reserve2 AS reserve2, p.creator AS creator, p.updater AS updater, p.create_time AS createTime, p.update_time AS updateTime, s.space_no AS spaceNo FROM end_park p LEFT JOIN area_info a ON p.area_id = a.id AND a.deleted = 0 LEFT JOIN user_info u ON p.operator_id = u.id AND u.deleted = 0 LEFT JOIN parking_space_info s ON p.space_id = s.id AND s.deleted = 0 WHERE p.deleted = 0
AND p.plate_no LIKE CONCAT('%', #{reqVO.plateNo}, '%')
AND p.space_id = #{reqVO.spaceId}
AND p.end_time BETWEEN FROM_UNIXTIME(#{reqVO.endTimeNew[0]}) AND FROM_UNIXTIME(#{reqVO.endTimeNew[1]})
AND p.status = #{reqVO.status}
AND p.area_id = #{reqVO.areaId}
AND p.operator_id = #{reqVO.operatorId}
AND p.order_no LIKE CONCAT('%', #{reqVO.orderNo}, '%')
AND p.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
ORDER BY p.id DESC

SELECT DATE(p.end_time) AS date, COUNT(*) AS count FROM end_park p WHERE p.deleted = 0 AND p.end_time BETWEEN FROM_UNIXTIME(#{reqVO.startTime}) AND DATE_ADD(FROM_UNIXTIME(#{reqVO.endTime}), INTERVAL 1 DAY)
AND p.area_id = #{reqVO.areaId}
GROUP BY DATE(p.end_time) ORDER BY date ASC
